onOptionChange:
{{
  storeValue('activeReport', ReportSelect.selectedOptionValue);
  if (ReportSelect.selectedOptionValue === 'Bill Health Report') {
    fetch_analytics_data.run();
    fetch_warnings.run(); fetch_late_bills.run(); fetch_late_fees.run(); fetch_account_status.run();
    fetch_notifications.run(); fetch_received_bills.run(); fetch_bill_accounts.run(); fetch_building_types.run();
  } else if (ReportSelect.selectedOptionValue === 'Monthly Attributes Report') {
    fetch_ma_usage.run(); fetch_monthly_attributes.run(); MT_MonthlyAttributesHelper.setDefaults();
  } else if (ReportSelect.selectedOptionValue === 'EE Project Analytics') {
    fetch_analytics_data.run();
  } else {
    fetch_analytics_data.run();
  }
}}

